package cn.mop.domain.monitoring;
import java.time.*;
import java.util.*;
import cn.mop.domain.monitoring.MonitoringEventPipeline.NoiseLayer;
/** Counts recorded noise-ledger facts, not final notifications, delivery receipts or collector health. */
public interface EventNoiseTrendReader {
 String VERSION="MOP_EVENT_NOISE_TREND_V1";
 long MAX=9007199254740991L;
 enum Window { HOURS_24(24,3600),DAYS_7(28,21600),DAYS_30(30,86400);public final int buckets,seconds;Window(int buckets,int seconds){this.buckets=buckets;this.seconds=seconds;}public long durationSeconds(){return (long)buckets*seconds;}}
 record Access(UUID tenantId,UUID actorId,long permissionVersion){public Access{Objects.requireNonNull(tenantId);Objects.requireNonNull(actorId);if(permissionVersion<1||permissionVersion>MAX)throw new IllegalArgumentException("Invalid trend access");}}
 record Bucket(Instant from,Instant to,Map<NoiseLayer,Long> layers){public Bucket{Objects.requireNonNull(from);Objects.requireNonNull(to);layers=Map.copyOf(layers);if(!from.isBefore(to)||layers.size()!=NoiseLayer.values().length||layers.values().stream().anyMatch(v->v<0||v>MAX)||layers.get(NoiseLayer.MERGE)>layers.get(NoiseLayer.RAW_INTAKE))throw new IllegalArgumentException("Invalid noise bucket");}public long rawCount(){return layers.get(NoiseLayer.RAW_INTAKE);}public long afterFingerprintMergeCount(){return rawCount()-layers.get(NoiseLayer.MERGE);}}
 record Marker(UUID recordId,UUID eventId,String ruleName,String severity,Instant recordedAt){public Marker{Objects.requireNonNull(recordId);Objects.requireNonNull(eventId);Objects.requireNonNull(recordedAt);if(ruleName==null||ruleName.isBlank()||ruleName.length()>128||!Set.of("DISASTER","HIGH","AVERAGE","WARNING","INFO").contains(severity))throw new IllegalArgumentException("Invalid recorded event marker");}}
 record RecordCursor(Instant recordedAt,UUID id){public RecordCursor{Objects.requireNonNull(recordedAt);Objects.requireNonNull(id);if(recordedAt.getNano()%1000000!=0)throw new IllegalArgumentException("Invalid record cursor");}}
 record RawRecord(UUID id,UUID eventId,Instant recordedAt,String detail){public RawRecord{Objects.requireNonNull(id);Objects.requireNonNull(eventId);Objects.requireNonNull(recordedAt);if(detail==null||detail.isBlank()||detail.length()>500)throw new IllegalArgumentException("Invalid raw ledger record");}}
 record RecordPage(Access access,Instant from,Instant to,Instant observedAt,int pageSize,long totalCount,List<RawRecord> items,RecordCursor next){public RecordPage{Objects.requireNonNull(access);Objects.requireNonNull(from);Objects.requireNonNull(to);Objects.requireNonNull(observedAt);items=List.copyOf(items);if(!from.isBefore(to)||to.isAfter(observedAt)||pageSize<1||pageSize>50||totalCount<0||totalCount>MAX||items.size()>pageSize||items.size()>totalCount)throw new IllegalArgumentException("Invalid raw detail page");RawRecord prior=null;var ids=new HashSet<UUID>();for(var row:items){if(!ids.add(row.id())||row.recordedAt().isBefore(from)||!row.recordedAt().isBefore(to)||prior!=null&&(row.recordedAt().isAfter(prior.recordedAt())||row.recordedAt().equals(prior.recordedAt())&&row.id().toString().compareTo(prior.id().toString())>=0))throw new IllegalArgumentException("Invalid raw detail order/scope");prior=row;}if(next!=null&&(items.size()!=pageSize||!next.id().equals(prior.id())||!next.recordedAt().equals(prior.recordedAt())))throw new IllegalArgumentException("Invalid detail cursor");}}
 record Snapshot(Access access,Window window,Instant observedAt,List<Bucket> buckets,Map<NoiseLayer,Long> totals,List<Marker> markers,boolean markersTruncated){public Snapshot(Access access,Window window,Instant observedAt,List<Bucket> buckets,Map<NoiseLayer,Long> totals){this(access,window,observedAt,buckets,totals,List.of(),false);}
 public Snapshot{markers=List.copyOf(markers);if(markers.size()>8||markersTruncated&&markers.size()!=8||window!=Window.HOURS_24&&(!markers.isEmpty()||markersTruncated))throw new IllegalArgumentException("Invalid marker budget");var markerIds=new HashSet<UUID>();Marker previous=null;for(var marker:markers){if(!markerIds.add(marker.recordId())||marker.recordedAt().isBefore(observedAt.minusSeconds(window.durationSeconds()))||!marker.recordedAt().isBefore(observedAt)||previous!=null&&(marker.recordedAt().isAfter(previous.recordedAt())||marker.recordedAt().equals(previous.recordedAt())&&marker.recordId().toString().compareTo(previous.recordId().toString())>=0))throw new IllegalArgumentException("Invalid marker scope/order");previous=marker;}Objects.requireNonNull(access);Objects.requireNonNull(window);Objects.requireNonNull(observedAt);buckets=List.copyOf(buckets);totals=Map.copyOf(totals);if(buckets.size()!=window.buckets||totals.size()!=NoiseLayer.values().length)throw new IllegalArgumentException("Invalid trend size");var from=observedAt.minusSeconds(window.durationSeconds());var sums=new EnumMap<NoiseLayer,Long>(NoiseLayer.class);for(var layer:NoiseLayer.values())sums.put(layer,0L);for(int i=0;i<buckets.size();i++){var b=buckets.get(i);if(!b.from().equals(from.plusSeconds((long)i*window.seconds))||!b.to().equals(b.from().plusSeconds(window.seconds)))throw new IllegalArgumentException("Invalid common bucket boundary");for(var layer:NoiseLayer.values())sums.put(layer,Math.addExact(sums.get(layer),b.layers().get(layer)));}if(!sums.equals(totals)||totals.values().stream().anyMatch(v->v<0||v>MAX))throw new IllegalArgumentException("Invalid complete layer totals");}}
 record Aggregated(int bucket,NoiseLayer layer,long count){}
 static Snapshot assemble(Access access,Window window,Instant observed,List<Aggregated> rows){
  Objects.requireNonNull(observed);if(observed.getNano()%1000000!=0)throw new IllegalArgumentException("Millisecond database time required");
  var values=new ArrayList<EnumMap<NoiseLayer,Long>>();for(int i=0;i<window.buckets;i++){var map=new EnumMap<NoiseLayer,Long>(NoiseLayer.class);for(var layer:NoiseLayer.values())map.put(layer,0L);values.add(map);}var keys=new HashSet<String>();
  for(var row:rows){if(row==null||row.layer()==null||row.bucket()<0||row.bucket()>=window.buckets||row.count()<1||row.count()>MAX||!keys.add(row.bucket()+":"+row.layer()))throw new IllegalArgumentException("Invalid database aggregate");values.get(row.bucket()).put(row.layer(),row.count());}
  var from=observed.minusSeconds(window.durationSeconds());var buckets=new ArrayList<Bucket>();var totals=new EnumMap<NoiseLayer,Long>(NoiseLayer.class);for(var layer:NoiseLayer.values())totals.put(layer,0L);
  for(int i=0;i<window.buckets;i++){buckets.add(new Bucket(from.plusSeconds((long)i*window.seconds),from.plusSeconds((long)(i+1)*window.seconds),values.get(i)));for(var layer:NoiseLayer.values())totals.put(layer,Math.addExact(totals.get(layer),values.get(i).get(layer)));}
  return new Snapshot(access,window,observed,buckets,totals);
 }
 Snapshot read(Access access,Window window);
 RecordPage records(Access access,Instant from,Instant to,RecordCursor before,int pageSize);
}
